#include "quake/frame3d.hpp"
#include "quake/newmark.hpp"
#include <iomanip>
#include <iostream>
#include <vector>
using namespace quake;
static int nid(int s,int ix,int iy){return 10000*s+100*ix+iy;}
static ASCE41HingeParams hp(){ASCE41HingeParams p;p.Ke=50000;p.posFy=p.negFy=8;p.hardening_ratio=.02;p.pos_a=p.neg_a=.006;p.pos_b=p.neg_b=.04;p.pos_f=p.neg_f=.06;p.pos_c=p.neg_c=.20;p.pos_drop_span=p.neg_drop_span=.002;p.pos_io=p.neg_io=.002;p.pos_ls=p.neg_ls=.010;p.pos_cp=p.neg_cp=.020;p.lambda_strength=.10;p.lambda_unloading=.12;p.cyclic_exponent=1.0;return p;}
static CompiledFrame3D model(int stories,bool updated){Frame3DBuilder b;constexpr double h=3.5,L=6,E=25000,G=10000;for(int s=0;s<=stories;++s)for(int ix=0;ix<2;++ix)for(int iy=0;iy<2;++iy){double m=s?.25:0;b.add_node(nid(s,ix,iy),ix*L,iy*L,s*h,m,m,.02*m);if(!s)b.fix(nid(s,ix,iy));}int eid=1,sid=1,did=900000;auto p=hp();for(int s=1;s<=stories;++s){double P=10.0*(stories-s+1);for(int ix=0;ix<2;++ix)for(int iy=0;iy<2;++iy)b.add_elastic_frame(eid++,nid(s-1,ix,iy),nid(s,ix,iy),E,G,2,.3,.55,.55,1,0,0,P);for(int iy=0;iy<2;++iy){int jl=nid(s,0,iy),jr=nid(s,1,iy),dl=did++,dr=did++;b.add_node(dl,0,iy*L,s*h);b.add_node(dr,L,iy*L,s*h);for(auto d:{Dof3D::UX,Dof3D::UY,Dof3D::UZ,Dof3D::RX,Dof3D::RZ}){b.equal_dof(jl,dl,d);b.equal_dof(jr,dr,d);}b.add_elastic_frame(eid++,dl,dr,E,G,1.5,.2,.35,.35,0,1,0);b.add_asce41_hinge(sid++,jl,Dof3D::RY,dl,Dof3D::RY,p);b.add_asce41_hinge(sid++,jr,Dof3D::RY,dr,Dof3D::RY,p);}}
 b.set_rayleigh(.02,.0005);b.set_ground_direction(Dof3D::UX);b.set_response(nid(stories,0,0),Dof3D::UX);std::vector<int> sn;for(int s=1;s<=stories;++s)sn.push_back(nid(s,0,0));b.set_story_nodes(sn,Dof3D::UX);b.set_updated_pdelta(updated);return b.compile();}
static const char* term(AnalysisTermination t){return t==AnalysisTermination::Completed?"completed":t==AnalysisTermination::PhysicalCollapse?"physical-collapse":t==AnalysisTermination::InitialInstability?"initial-instability":"numerical-failure";}
int main(int argc,char**argv){int stories=argc>1?std::stoi(argv[1]):6;double amp=argc>2?std::stod(argv[2]):4.0;bool updated=argc>3?std::stoi(argv[3])!=0:true;int smode=argc>4?std::stoi(argv[4]):2;LinearStrategy strategy=smode==0?LinearStrategy::FullFactorization:(smode==1?LinearStrategy::SamePatternRefactorization:LinearStrategy::Woodbury);double dt=.005;auto m=model(stories,updated);auto gm=synthetic_ground_motion(500,dt,amp);RobustNewmarkOptions o;o.max_iterations=60;o.max_subdivisions=8;o.max_backtracks=12;o.nonmonotone_line_search_factor=1.10;o.return_numerical_failure=true;o.collapse.max_story_drift_ratio=.06;o.collapse.max_failed_components=2;o.collapse.tangent_check_interval=25;o.collapse.min_tangent_ratio=.02;o.collapse.classify_unrecoverable_lateral_loss_as_collapse=true;o.direct_rank_fraction=argc>5?std::stod(argv[5]):.35;auto r=run_newmark_robust(m,gm,dt,strategy,o);auto none=static_cast<std::size_t>(-1);std::cout<<std::fixed<<std::setprecision(6)<<"stories="<<stories<<" dof="<<m.dof()<<" hinges="<<m.nonlinear_count()<<" generalized_basis="<<m.generalized_state_update_basis().cols()<<" amp="<<amp<<" updated_pdelta="<<updated<<"\n"<<"termination="<<term(r.termination)<<" step="<<r.termination_step<<" time="<<r.termination_time<<" reason="<<r.termination_reason<<"\n"<<"max_roof="<<r.stats.max_roof_abs<<" max_drift_ratio="<<r.max_story_drift_ratio<<" min_tangent_ratio="<<r.stats.minimum_tangent_ratio<<" min_tangent_eig="<<r.stats.minimum_tangent_eigenvalue<<"\n"<<"max_lateral_loss_components="<<r.max_components_lateral_loss<<" max_failed_components="<<r.max_failed_components<<"\n"<<"first_IO="<<(r.first_io_step==none?-1:(long long)r.first_io_step)<<" first_LS="<<(r.first_ls_step==none?-1:(long long)r.first_ls_step)<<" first_CP="<<(r.first_cp_step==none?-1:(long long)r.first_cp_step)<<" first_E="<<(r.first_lateral_loss_step==none?-1:(long long)r.first_lateral_loss_step)<<" first_F="<<(r.first_component_failure_step==none?-1:(long long)r.first_component_failure_step)<<"\n"<<"trial_lateral_loss_events="<<r.stats.nonlinear_lateral_loss<<" trial_failure_events="<<r.stats.nonlinear_failure_events<<" deterioration_events="<<r.stats.nonlinear_deterioration_events<<"\n"<<"reduced_pivot_ratio="<<r.stats.minimum_reduced_pivot_ratio<<"\n"<<"energy(input,internal,damping,kinetic,balance)="<<r.stats.input_energy<<","<<r.stats.internal_work<<","<<r.stats.damping_energy<<","<<r.stats.kinetic_energy<<","<<r.stats.energy_balance_error<<" rel="<<r.stats.energy_balance_relative_error<<"\n"<<"fail_reasons(linear,line_search,maxit)="<<r.stats.linear_solve_failures<<","<<r.stats.line_search_failures<<","<<r.stats.max_iteration_failures<<"\n"<<"newton="<<r.stats.newton_iterations<<" max_update_rank="<<r.stats.max_generalized_update_rank<<" generalized_solves="<<r.stats.generalized_update_solves<<" factorizations="<<r.stats.global_factorizations<<" direct_fallbacks="<<r.stats.direct_fallbacks<<" subdivisions="<<r.stats.subdivided_steps<<" elapsed="<<r.stats.elapsed_seconds<<"\n";}
